/*
  Kitobni ID orqali topish.
  DIQQAT: Bu funksiya faqat BIR MARTA yozilgan.
*/

export function getBookById(id) {
  return books.find(
    (book) => String(book.id) === String(id)
  );
}

export function getRelatedBooks(bookId) {
  const currentBook = getBookById(bookId);

  if (!currentBook) {
    return [];
  }

  return books
    .filter(
      (book) =>
        String(book.id) !== String(bookId) &&
        book.category === currentBook.category
    )
    .slice(0, 4);
}       